export function caseDeepDive(id){const d=useCaseDepth[id];if(!d)return '';const ref=references[id];return `<div class="case-deep-dive"><div class="company-heading"><span class="company-kicker">DEPLOYMENT &amp; CUSTOMIZATION DEEP DIVE</span><h3>Make the design fit the business</h3><small>Proposed options · not features already implemented in this workshop</small></div><section class="case-depth-section"><h4>A fuller company scenario</h4><p>${e(d[0])}</p></section><details open><summary>Configuration choices · adapt the supported product</summary><div class="company-detail"><p>${e(d[1])}</p></div></details><details open><summary>Custom integrations · what you could build around it</summary><div class="company-detail"><p>${e(d[2])}</p>${ref?`<p class="company-reference">Supported extension reference: <a href="${ref[1]}" target="_blank" rel="noopener noreferrer">${ref[0]} ↗</a>. Check current event, tenant and licensing support before implementation.</p>`:''}</div></details><details open><summary>Tradeoffs, failure cases and design decisions</summary><div class="company-detail"><p>${e(d[3])}</p></div></details><div class="company-discussion"><b>Turn customization into a delivery decision</b><p>Identify the specific gap the standard configuration cannot solve. Name the system of record, integration owner and approver; agree the minimum data exchanged and the allowed permissions. Define failure behavior, audit evidence and acceptance tests before estimating or building the extension.</p></div></div>`;}
